ALTER TABLE "users" ADD CONSTRAINT "users_platform_capabilities_staff_array" CHECK ("users"."platform_capabilities" IS NULL OR (CASE WHEN jsonb_typeof("users"."platform_capabilities") = 'array' THEN jsonb_array_length("users"."platform_capabilities") <= 17 ELSE false END AND "users"."platform_role" <> 'user'));